import pytest
from project import parse_limit
@pytest.mark.parametrize("raw,default,expected", [(None, 7, 7), ("0", 7, 0), ("12", 7, 12)])
def test_existing(raw, default, expected):
    assert parse_limit(raw, default) == expected
@pytest.mark.parametrize("raw", ["", " ", "\t\n"])
def test_missing_uses_supplied_default(raw):
    assert parse_limit(raw, 7) == 7
@pytest.mark.parametrize("raw", ["-1", "bad", "1.5"])
def test_invalid(raw):
    with pytest.raises(ValueError):
        parse_limit(raw)
